export const CELLS=[{q:0,r:0},{q:1,r:0}];
export const key=(q,r)=>`${q},${r}`;
export const distance=(a,b)=>Math.hypot(a.q-b.q,a.r-b.r);
export function validate(c){for(const [k,max] of [['archers',4],['peasants',6],['zombies',12]])if(!Number.isInteger(c[k])||c[k]<0||c[k]>max)throw Error(`Invalid ${k} count`);if(!c.zombies||!c.archers&&!c.peasants)throw Error('Both sides need characters');return {...c};}
export function fresh(counts={archers:1,peasants:0,zombies:2},prefab='duel'){return {version:2,revision:0,counts:validate(counts),prefab,phase:'placing',time:0,tick:0,tiles:[],actors:[],effects:[],kills:0,rebirths:0,cutscene:null,paused:false,nextId:1};}
export const connected=s=>s.tiles.length===2;
export const ready=connected;
export const hand=s=>['humans','zombies'].filter(type=>!s.tiles.some(t=>t.type===type));
export function path(s,a,b){return connected(s)?[a,b]:null;}
export function place(s,type,q,r){if(s.phase!=='placing')throw Error('Reset before placing cards');if(!hand(s).includes(type))throw Error('Card already placed');if(!CELLS.some(c=>c.q===q&&c.r===r)||s.tiles.some(t=>t.q===q&&t.r===r))throw Error('Choose an empty card socket');s.tiles.push({id:`card-${s.nextId++}`,type,q,r,knives:type==='humans'?s.counts.peasants:0});s.revision++;if(ready(s))start(s);return s;}
export function start(s){if(!ready(s)||s.phase!=='placing')throw Error('Place both cards');s.phase='intro';s.cutscene='ARCHERS VS ZOMBIES';s.cutUntil=1.6;const h=s.tiles.find(t=>t.type==='humans'),z=s.tiles.find(t=>t.type==='zombies');for(const [role,n,t] of [['archer',s.counts.archers,h],['peasant',s.counts.peasants,h],['zombie',s.counts.zombies,z]])for(let i=0;i<n;i++){const q=t.q+(role==='zombie'?.18:-.16)+(i%3)*.10,r=(Math.floor(i/3)-.5)*.14;s.actors.push({id:`actor-${s.nextId++}`,role,kind:role==='zombie'?'zombie':'human',q,r,hp:3,maxHp:3,cooldown:i*.17,offset:i,deadAt:null,risen:false,shelteredUntil:role==='peasant'?3.5:null});}s.revision++;}
function effect(s,kind,a,b){s.effects.push({id:s.nextId++,kind,q:a.q,r:a.r,to:b?{q:b.q,r:b.r}:null,at:s.time});}
function hurt(s,a,n){if(a.hp<=0)return;a.hp=Math.max(0,a.hp-n);effect(s,'hit',a);if(!a.hp){a.deadAt=s.time;effect(s,'death',a);if(a.kind==='zombie')s.kills++;}}
// Fixed 50 ms simulation ticks are identical in forecasts and visible playback.
export function step(s,dt){if(!Number.isFinite(dt)||dt<=0||dt>1)throw Error('Invalid time step');if(s.paused||!['intro','battle'].includes(s.phase))return;s.remainder=(s.remainder||0)+dt;while(s.remainder>=.05-1e-9){s.remainder-=.05;tick(s);if(!['intro','battle'].includes(s.phase)){s.remainder=0;break;}}}
function tick(s){s.tick++;s.time=s.tick*.05;s.revision++;s.effects=s.effects.filter(e=>s.time-e.at<1.5);if(s.phase==='intro'){if(s.time>=s.cutUntil){s.phase='battle';s.cutscene=null;}return;}if(s.cutscene&&s.time>=s.cutUntil)s.cutscene=null;
for(const a of s.actors)if(a.kind==='human'&&!a.hp&&!a.risen&&s.time-a.deadAt>=1.6){a.kind='zombie';a.role='zombie';a.weapon=false;a.shelteredUntil=null;a.hp=3;a.risen=true;a.cooldown=.7;a.deadAt=null;s.rebirths++;effect(s,'rebirth',a);s.cutscene='A FALLEN FRIEND RISES';s.cutUntil=s.time+1.2;}
for(const a of s.actors){if(!a.hp)continue;a.cooldown-=.05;if(a.shelteredUntil){if(s.time<a.shelteredUntil)continue;a.shelteredUntil=null;a.weapon=true;s.tiles.find(t=>t.type==='humans').knives--;effect(s,'knife',a);}
const enemy=s.actors.filter(b=>b.kind!==a.kind&&b.hp>0&&!b.shelteredUntil).sort((x,y)=>distance(a,x)-distance(a,y))[0];if(!enemy)continue;const d=distance(a,enemy),range=a.role==='archer'?2:.16;if(d<=range){if(a.cooldown<=0){effect(s,a.role==='archer'?'arrow':'hit',a,enemy);hurt(s,enemy,a.role==='archer'||a.weapon?2:1);a.cooldown=a.role==='archer'?1.35:a.weapon?1:1.1;}}else{const n=Math.min(d,.05*(a.kind==='zombie'?.18:.23));a.q+=(enemy.q-a.q)*n/d;a.r+=(enemy.r-a.r)*n/d;}}
const alive=s.actors.filter(a=>a.hp>0),pending=s.actors.some(a=>a.kind==='human'&&!a.hp&&!a.risen);if(!alive.some(a=>a.kind==='human')&&!pending){s.phase='lost';s.cutscene='THE DEAD CLAIM THE FIELD';}else if(!alive.some(a=>a.kind==='zombie')&&!pending){s.phase='won';s.cutscene='THE LIVING HOLD THE LINE';}if(s.time>180){s.phase='lost';s.cutscene='THE FIELD IS LOST';}}
export function simulate(counts){const s=fresh(counts);place(s,'humans',0,0);place(s,'zombies',1,0);while(['intro','battle'].includes(s.phase))step(s,1);return {outcome:s.phase,seconds:Number(s.time.toFixed(2)),survivors:s.actors.filter(a=>a.kind==='human'&&a.hp>0).length,remainingHealth:s.actors.filter(a=>a.kind==='human'&&a.hp>0).reduce((n,a)=>n+a.hp,0),kills:s.kills,rebirths:s.rebirths};}
